}

// cachedFallback answers a failed latest-release resolution from the cache.
// The failure is only reported when the cache cannot answer at all — with the
// remediation on the second line, per house style.
func cachedFallback(stderr io.Writer, cacheRoot, url, doing string, cause error) (*Source, error) {
	cached := newestCachedTag(cacheRoot, url)
	if cached == "" {
		return nil, fmt.Errorf("%w\npin a cached release with --template-version (cache: %s)", cause, gitclone.CheckoutDir(cacheRoot, url))
	}
	fmt.Fprintf(stderr, "cannot %s; using cached templates %s\n", doing, cached)
	return &Source{Version: cached, root: checkoutDir(cacheRoot, url, cached)}, nil
}

// fetchFallback answers a failed clone from the cache: the newest cached
// release with both tags named, or the failure with the cache directory the
// user could clear or prime.
func fetchFallback(stderr io.Writer, cacheRoot, url, owner, repo, tag string, cause error) error {
	cached := newestCachedTag(cacheRoot, url)
	if cached == "" {
		return fmt.Errorf("%w\npin a cached release with --template-version (cache: %s)", cause, gitclone.CheckoutDir(cacheRoot, url))
	}
	fmt.Fprintf(stderr, "cannot fetch %s/%s@%s; using cached templates %s\n", owner, repo, tag, cached)
	return errUseCached{tag: cached}
}

// errUseCached carries the fallback decision out of fetchFallback without
// source.go's caller having to re-derive it.
type errUseCached struct{ tag string }

func (e errUseCached) Error() string { return "use cached " + e.tag }

