	}

	for _, name := range []string{"deploy-host", "deploy-component"} {
		tmpl, skeleton, err := lib.Open(name)
		if err != nil {
			t.Fatalf("Open(%q): %v", name, err)
		}
		if tmpl.Metadata.Name != name {
